mapper.select:
select gs.* from goods_shop gs left join sys_user_shop sus on sus.shop_id = gs.shop_id where 1 = 1 and sus.user_id = #{userId}
and shop_name like concat('%',#{shopName},'%')
order by gs.create_time desc

select g.goods_id, g.classify_id, g.goods_cover, g.goods_picture, g.create_time, g.sales_volume, g.`status`, g.pack_money, g.goods_money, g.original_money, g.shop_id, gi.goods_name, gi.goods_synopsis, gi.goods_describe, gi.goods_label, gi.language_type, gi.language_name, gs.classify_name as classifyName from goods g left join goods_i18n gi on g.goods_id = gi.goods_id left join goods_classify_i18n gs on g.classify_id = gs.classify_id and gs.language_type = #{languageType} where 1 = 1
and g.classify_id = #{classifyId}
and g.goods_name like concat('%',#{goodsName},'%')
and g.status = #{status}
and gi.language_type = #{languageType}
and g.shop_id = 0 order by g.create_time desc

select g.goods_id, g.classify_id, g.goods_cover, g.goods_picture, g.create_time, g.sales_volume, g.`status`, g.pack_money, g.goods_money, g.original_money, g.shop_id, gi.goods_name, gi.goods_synopsis, gi.goods_describe, gi.goods_label, gi.language_type, gi.language_name, gci.classify_name as classifyName, gsr.inventory as inventory, gsr.status as gsrStatus from goods_shop_relevancy gsr left join goods g on gsr.goods_id = g.goods_id left join goods_i18n gi on g.goods_id = gi.goods_id left join goods_classify gc on g.classify_id = gc.classify_id left join goods_classify_i18n gci on gc.classify_id = gci.classify_id where gsr.shop_id = #{shopId} and g.status = 0
and g.goods_name like concat('%',#{goodsName},'%')
and g.classify_id = #{classifyId}
and gsr.status = #{status}
and gci.language_type = #{languageType} and gi.language_type = #{languageType}
order by gsr.create_time desc

select g.*, gc.classify_name as classifyName, gsr.inventory as inventory, gsr.status as gsrStatus
from goods_shop_relevancy gsr
         left join goods g on gsr.goods_id = g.goods_id
         left join goods_classify gc on g.classify_id = gc.classify_id
where gsr.shop_id = #{shopId}
  and gsr.goods_id = #{goodsId}

mapper.delete:
delete
from goods_shop_relevancy
where shop_id = #{shopId}
  and goods_id = #{goodsId}

mapper.update:
update goods_shop_relevancy
set status = #{status}
where shop_id = #{shopId}
  and goods_id = #{goodsId}

mapper.select:
select tor.*, gs.shop_name as shopName from tb_order tor left join goods_shop gs on tor.shop_id = gs.shop_id
where 1 = 1

    and tor.status = #{status}


    and tor.shop_id = #{shopId}


    and tor.order_number = #{orderNumber}


    and date_format(tor.create_time,'%Y-%m-%d')=date_format(#{date},'%Y-%m-%d')


    and date_format(tor.create_time,'%Y-%m')=date_format(#{date},'%Y-%m')


    and date_format(tor.create_time,'%Y')=date_format(#{date},'%Y')

order by tor.pay_time desc
